const ids = $input.first().json;

const html = `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Setup Completado</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 700px; margin: 40px auto; padding: 20px; background: #f9fafb; }
    h1 { color: #16a34a; }
    .card { background: white; border-radius: 12px; padding: 28px; box-shadow: 0 2px 8px rgba(0,0,0,.1); margin-bottom: 20px; }
    .badge { display: inline-block; background: #dcfce7; color: #166534; border-radius: 6px; padding: 2px 10px; font-size: 13px; font-weight: 600; margin-bottom: 8px; }
    label { display: block; font-size: 13px; color: #6b7280; margin-top: 12px; margin-bottom: 4px; font-weight: 500; }
    .id-box { background: #f3f4f6; border: 1px solid #d1d5db; border-radius: 6px; padding: 10px 14px; font-family: monospace; font-size: 14px; word-break: break-all; cursor: pointer; transition: background .15s; }
    .id-box:hover { background: #e5e7eb; }
    .copy-hint { font-size: 11px; color: #9ca3af; margin-top: 3px; }
    .steps { background: #eff6ff; border-left: 4px solid #3b82f6; border-radius: 0 8px 8px 0; padding: 16px 20px; }
    .steps ol { margin: 8px 0 0; padding-left: 20px; }
    .steps li { margin-bottom: 6px; font-size: 14px; color: #1e40af; }
    .steps code { background: #dbeafe; padding: 1px 5px; border-radius: 3px; font-size: 13px; }
  </style>
</head>
<body>
  <div class="card">
    <span class="badge">✅ Setup completado</span>
    <h1>IDs generados correctamente</h1>
    <p>Copia estos tres IDs y pégalos en los workflows 1, 2 y 3 donde se indica. Haz clic en cada ID para copiarlo.</p>

    <label>📊 Spreadsheet (copia) → reemplaza <code>TU_SPREADSHEET_COPIA_ID</code> en workflows 1, 2 y 3</label>
    <div class="id-box" onclick="navigator.clipboard.writeText(this.innerText)">${ids.spreadsheet_copia_id}</div>
    <div class="copy-hint">Haz clic para copiar</div>

    <label>📁 Carpeta Contratos → reemplaza <code>TU_CARPETA_CONTRATOS_ID</code> en workflow 2</label>
    <div class="id-box" onclick="navigator.clipboard.writeText(this.innerText)">${ids.carpeta_contratos_id}</div>
    <div class="copy-hint">Haz clic para copiar</div>

    <label>📁 Carpeta Facturas → reemplaza <code>TU_CARPETA_FACTURAS_ID</code> en workflow 3</label>
    <div class="id-box" onclick="navigator.clipboard.writeText(this.innerText)">${ids.carpeta_facturas_id}</div>
    <div class="copy-hint">Haz clic para copiar</div>
  </div>

  <div class="steps">
    <strong>Próximos pasos:</strong>
    <ol>
      <li>Abre el workflow <strong>1-stock-management</strong> → busca el nodo Google Sheets → reemplaza <code>TU_SPREADSHEET_COPIA_ID</code></li>
      <li>Abre el workflow <strong>2-contract-generator</strong> → reemplaza <code>TU_SPREADSHEET_COPIA_ID</code> y <code>TU_CARPETA_CONTRATOS_ID</code></li>
      <li>Abre el workflow <strong>3-invoice-generator</strong> → reemplaza <code>TU_SPREADSHEET_COPIA_ID</code> y <code>TU_CARPETA_FACTURAS_ID</code></li>
      <li>En Google Sheets, abre la copia y crea las 3 pestañas: <strong>Stock</strong>, <strong>Contratos</strong>, <strong>Facturas</strong> con las columnas del README</li>
      <li>Activa los workflows 1, 2 y 3</li>
    </ol>
  </div>
</body>
</html>`;

return [{ json: { html } }];
